import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.BZohXCq9.js";const m=JSON.parse('{"title":"Admin Dashboard -> Student Management (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/admin-dashboard/student-management.md","filePath":"modules/admin-dashboard/student-management.md"}'),n={name:"modules/admin-dashboard/student-management.md"};function l(s,e,i,r,c,u){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="admin-dashboard-student-management-deep" tabindex="-1">Admin Dashboard -&gt; Student Management (deep) <a class="header-anchor" href="#admin-dashboard-student-management-deep" aria-label="Permalink to &quot;Admin Dashboard -&gt; Student Management (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>admin-dashboard</code><br><strong>Feature:</strong> <code>student-management</code><br><strong>Route:</strong> <code>/admin-dashboard/StudentManagement</code></p><p>This module lets admins browse students, filter them by admin-facing attributes, inspect details, and bulk-delete selected students.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show all students with lesson-summary metadata.</li><li>Filter by verification state, lesson count, location, and created-at range.</li><li>Open a student detail modal.</li><li>Bulk-delete selected students.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/admin-dashboard/StudentManagement.tsx</code></td><td>Main route page</td><td>Calls <code>GET_ALL_STUDENTS_ADMIN</code> and <code>DELETE_STUDENTS</code>; manages filters, selection, delete mode, and detail modal state.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/StudentFilterPopover.tsx</code></td><td>Filter UI</td><td>Returns admin filter choices back to the page.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/StudentCard.tsx</code></td><td>Student card/list item</td><td>Displays summary data and selection control.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/StudentDetailModel.tsx</code></td><td>Detail modal</td><td>Shows expanded student information.</td></tr><tr><td><code>Frontend/src/components/AdminComponents/StudentDeleteConfirmationModal.tsx</code></td><td>Delete confirmation dialog</td><td>Used for bulk delete confirmation.</td></tr><tr><td><code>Frontend/src/graphql/Queries/StudentQueries.ts</code></td><td>GraphQL operations</td><td>Defines <code>GET_ALL_STUDENTS_ADMIN</code> and <code>DELETE_STUDENTS</code>.</td></tr><tr><td><code>Frontend/src/types/Student.ts</code></td><td>TS interfaces</td><td>Defines <code>StudentDetail</code> and <code>StudentFilterOptions</code>.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-all-students-admin" tabindex="-1"><code>GET_ALL_STUDENTS_ADMIN</code> <a class="header-anchor" href="#get-all-students-admin" aria-label="Permalink to &quot;`GET_ALL_STUDENTS_ADMIN`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/StudentQueries.ts</code></li><li>Query field: <code>allStudentsWithLessonStats</code></li><li>Returns: <ul><li>student profile basics</li><li>documents</li><li>verification state</li><li>derived fields such as <code>remainingHours</code>, <code>lastLesson</code>, <code>totalLessons</code>, <code>bookedLessons</code>, <code>cancelledLessons</code></li></ul></li><li>Used by: <code>StudentManagement.tsx</code></li></ul><h3 id="delete-students" tabindex="-1"><code>DELETE_STUDENTS</code> <a class="header-anchor" href="#delete-students" aria-label="Permalink to &quot;`DELETE_STUDENTS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/StudentQueries.ts</code></li><li>Mutation field: <code>deleteStudents(studentIds: [ID!]!)</code></li><li>Used by: <code>StudentManagement.tsx</code></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs.js</code></li><li>Relevant query field: <ul><li><code>allStudentsWithLessonStats: [StudentWithLessonStats!]</code></li></ul></li><li>Relevant mutation field: <ul><li><code>deleteStudents(studentIds: [ID!]!): DeleteStudentsResponse!</code></li></ul></li><li>Relevant types: <ul><li><code>StudentWithLessonStats</code></li><li><code>DeleteStudentsResponse</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers.js</code></li><li>Relevant query resolver: <ul><li><code>allStudentsWithLessonStats</code><ul><li>Admin-only</li><li>Loads all students</li><li>Loads each student’s bookings from <code>studentBookingModel</code></li><li>Derives: <ul><li><code>totalLessons</code></li><li><code>bookedLessons</code></li><li><code>cancelledLessons</code></li><li><code>lastLesson</code></li><li><code>remainingHours</code></li></ul></li></ul></li></ul></li><li>Relevant mutation resolver: <ul><li><code>deleteStudents</code><ul><li>Admin-only</li><li>Deletes students with <code>Student.deleteMany({ _id: { $in: studentIds } })</code></li><li>Returns <code>{ success, message }</code></li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/User</code></td><td>Source of <code>Student</code> documents</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Used to derive lesson counts and last lesson</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Admin opens <code>StudentManagement.tsx</code>.</li><li><code>GET_ALL_STUDENTS_ADMIN</code> loads student records enriched with lesson stats.</li><li>Frontend derives unique location options and applies client-side filters with <code>useMemo</code>.</li><li>Admin opens <code>StudentDetailModal</code> for one student or enters delete mode.</li><li>Confirm delete -&gt; <code>DELETE_STUDENTS</code>.</li><li>Backend deletes the selected students and frontend refetches.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>Filters are all client-side after the initial GraphQL fetch.</li><li>The query is purposely admin-specific and broader than the smaller student-facing queries elsewhere in the app.</li><li><code>fetchPolicy: &quot;network-only&quot;</code> is used here to avoid stale admin data on mount.</li></ul>',23)])])}const p=t(n,[["render",l]]);export{m as __pageData,p as default};
